PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS vocabulary_collections (
  id TEXT PRIMARY KEY,
  owner_child_id TEXT REFERENCES child_profiles(id) ON DELETE CASCADE,
  collection_type TEXT NOT NULL CHECK(collection_type IN ('system','custom')),
  code TEXT,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  cefr_level TEXT,
  stage TEXT,
  source_note TEXT,
  sort_order INTEGER NOT NULL DEFAULT 100,
  status TEXT NOT NULL DEFAULT 'published',
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_vocab_collections_owner ON vocabulary_collections(owner_child_id,collection_type,status,sort_order);
CREATE TABLE IF NOT EXISTS vocabulary_collection_items (
  collection_id TEXT NOT NULL REFERENCES vocabulary_collections(id) ON DELETE CASCADE,
  vocabulary_id TEXT NOT NULL REFERENCES vocabulary_items(id) ON DELETE CASCADE,
  item_order INTEGER NOT NULL DEFAULT 0,
  added_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(collection_id,vocabulary_id)
);
CREATE INDEX IF NOT EXISTS idx_vocab_collection_items_order ON vocabulary_collection_items(collection_id,item_order,vocabulary_id);
CREATE TABLE IF NOT EXISTS learner_vocabulary_training_settings (
  child_id TEXT PRIMARY KEY REFERENCES child_profiles(id) ON DELETE CASCADE,
  active_collection_id TEXT REFERENCES vocabulary_collections(id) ON DELETE SET NULL,
  daily_target INTEGER NOT NULL DEFAULT 10,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS vocabulary_training_progress (
  child_id TEXT NOT NULL REFERENCES child_profiles(id) ON DELETE CASCADE,
  vocabulary_id TEXT NOT NULL REFERENCES vocabulary_items(id) ON DELETE CASCADE,
  pronunciation_score REAL NOT NULL DEFAULT 0,
  recognition_score REAL NOT NULL DEFAULT 0,
  listening_score REAL NOT NULL DEFAULT 0,
  spelling_score REAL NOT NULL DEFAULT 0,
  usage_score REAL NOT NULL DEFAULT 0,
  mastery REAL NOT NULL DEFAULT 0,
  repetitions INTEGER NOT NULL DEFAULT 0,
  correct_count INTEGER NOT NULL DEFAULT 0,
  incorrect_count INTEGER NOT NULL DEFAULT 0,
  last_trained_at TEXT,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY(child_id,vocabulary_id)
);
CREATE TABLE IF NOT EXISTS vocabulary_training_events (
  id TEXT PRIMARY KEY,
  child_id TEXT NOT NULL REFERENCES child_profiles(id) ON DELETE CASCADE,
  collection_id TEXT REFERENCES vocabulary_collections(id) ON DELETE SET NULL,
  vocabulary_id TEXT NOT NULL REFERENCES vocabulary_items(id) ON DELETE CASCADE,
  mode TEXT NOT NULL CHECK(mode IN ('pronounce','meaning','dictation','definition_spelling','cloze')),
  correct INTEGER NOT NULL DEFAULT 0,
  response_text TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_vocab_training_events_child ON vocabulary_training_events(child_id,created_at);
